/* Repol Studio v2: roles, billing, profile, announcements and responsive shell. */
Object.assign(icons,{sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z"/>',wallet:'<path d="M20 7V4H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V7M21 12h-6v5h6M17 14.5h.1"/>',crown:'<path d="m3 6 5 5 4-8 4 8 5-5-2 13H5L3 6ZM6 22h12"/>',megaphone:'<path d="m3 10 17-7v18L3 14v-4ZM6 15l2 7h4l-2-6M20 9h3"/>',refresh:'<path d="M21 4v6h-6M3 20v-6h6M5 7a8 8 0 0 1 14 1M19 17a8 8 0 0 1-14-1"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="3"/><path d="M16 8V3H3v13h5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',tron:'<path d="m3 3 18 5-6 14L3 3Zm0 0 12 19V10L3 3Zm12 7 6-2"/>',arrowUp:'<path d="M12 20V4m-6 6 6-6 6 6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>'});
Object.assign(titleMap,{profile:'پروفایل من',wallet:'کیف پول',billing:'اشتراک و صورت‌حساب',notifications:'مرکز اعلان‌ها',contacts:'مخاطب‌ها',templates:'استودیوی قالب‌ها',admin:'مدیریت اصلی',adminUsers:'مدیریت کاربران',adminOrders:'سفارش‌ها و پرداخت',adminNotices:'مرکز انتشار',adminBusiness:'تنظیمات فروش',adminAudit:'تاریخچهٔ مدیریت'});
const accessKeys=['dashboard','rules','inbox','files','analytics','connections','contacts','templates'];
const demoPlans=[{id:'start',name:'شروع',days:30,priceIRR:8490000,description:'یک ماه برای شروع ارتباط‌های بهتر',features:['سناریوساز و آزمایش پاسخ','مدیریت مخاطب و فایل','پروفایل و مرکز اعلان‌ها']},{id:'growth',name:'رشد',days:90,priceIRR:25470000,description:'سه ماه برای ساختن عادت‌های بهتر',features:['همهٔ امکانات شروع','۹۰ روز دسترسی','مدیریت یکپارچهٔ گفتگوها']},{id:'studio',name:'استودیو',days:365,priceIRR:101880000,description:'یک سال همراه با ایده‌های بزرگ‌تر',features:['همهٔ امکانات رشد','۳۶۵ روز دسترسی','یک فضای کار منسجم']}];
const defaultBusiness={plans:demoPlans,support:'fesghli',cryptoAddress:'TBbC1YJDnyfwzVvuekbZnb2KuEwoPVDEes',cryptoNetwork:'TRON',cryptoEnabled:false,salesEnabled:false,trxPriceIRR:0};
let demoRole='admin',adminData=null,noticeFilter='all',userQuery='',orderFilter='all',catalog=null;
const money=n=>fa(Math.round(Number(n)/10)),when=n=>n?new Date(n).toLocaleDateString('fa-IR'):'—',shortEmail=v=>esc(v||'—');
function ensureStudio(){const d=state.data;if(!d)return;d.owner={role:state.demo?demoRole:'user',permissions:accessKeys,phone:'',bio:'',company:'',avatar:'violet',...d.owner};if(state.demo)d.owner.role=demoRole;d.settings={theme:localStorage.getItem('repol-theme')||'system',motion:true,compact:false,...d.settings};d.business??=structuredClone(defaultBusiness);d.subscription??={daysRemaining:state.demo?23:0,plan:state.demo?'growth':'free',expires:state.demo?Date.now()+23*86400000:0,active:state.demo};d.wallet??={balance:state.demo?1500000:0,currency:'IRR',ledger:[]};d.orders??=[];d.notifications??=state.demo?[{id:'welcome',title:'به استودیوی تازهٔ ریپل خوش آمدی',body:'تم دلخواهت را انتخاب کن و مدیریت کاربران، کیف پول و سناریوساز را تجربه کن.',type:'release',created:Date.now(),read_at:null},{id:'billing-demo',title:'یک تصویر روشن از اشتراکت',body:'این یک حساب نمایشی است. پرداخت واقعی در آن انجام نمی‌شود.',type:'info',created:Date.now()-3600000,read_at:null}]:[];d.contacts??=state.demo?[{id:'c1',name:'سارا محمدی',handle:'sara.design',tag:'علاقه‌مند',note:'علاقه‌مند به آموزش طراحی',created:Date.now()},{id:'c2',name:'علی رضایی',handle:'ali.studio',tag:'مشتری',note:'پیگیری دورهٔ پیشرفته',created:Date.now()}]:[];d.templates??=[];applyTheme();}
function applyTheme(){const s=state.data?.settings||{theme:localStorage.getItem('repol-theme')||'system',motion:true};const dark=s.theme==='dark'||s.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.motion=s.motion===false?'off':'on';document.documentElement.dataset.compact=s.compact?'yes':'no';}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
const originalPage=pageContent,originalBind=bind,originalAction=action,originalAuth=auth;
function fakeAdmin(){if(adminData)return adminData;const stamp=Date.now();adminData={business:structuredClone(state.data.business),users:[{id:'demo-self',...state.data.owner,name:'مدیر ریپل',email:'owner@example.com',role:'admin',status:'active',daysRemaining:0,permissions:accessKeys,created:stamp-864000000,ruleCount:4,balance:1500000},{id:'demo-u1',name:'مینا کریمی',email:'mina@example.com',phone:'',company:'استودیو مینا',avatar:'mint',role:'user',status:'active',daysRemaining:18,expires:stamp+18*86400000,plan:'growth',permissions:accessKeys,created:stamp-86400000,ruleCount:6,balance:0},{id:'demo-u2',name:'بردیا احمدی',email:'bardia@example.com',phone:'',company:'فروشگاه بردیا',avatar:'blue',role:'user',status:'active',daysRemaining:0,expires:0,plan:'free',permissions:accessKeys,created:stamp,ruleCount:2,balance:0}],orders:[{id:'demo-order',code:'RP-DEMO-1405',user_id:'demo-u2',name:'بردیا احمدی',email:'bardia@example.com',kind:'subscription',plan_id:'start',days:30,amount:8490000,currency:'IRR',method:'rial',status:'pending',created:stamp-3600000,expires:stamp+86400000,snapshot:{planName:'شروع',support:'fesghli'},proof:'سفارش نمونه برای بررسی گردش پرداخت',note:''}],announcements:[],audit:[{id:'audit-demo',actorName:'مدیر ریپل',action:'نسخهٔ نمایشی آماده شد',created:stamp,data:{}}]};return adminData;}
function isAdmin(){return state.data?.owner.role==='admin';}
function canPage(p){return !accessKeys.includes(p)||isAdmin()||state.data.owner.permissions.includes(p);}
go=async function(p){if(p.startsWith('admin')&&!isAdmin())return toast('این بخش مخصوص مدیریت اصلی است.');if(!canPage(p))return toast('دسترسی این بخش برای حسابت فعال نیست.');closeDialog();try{if(p.startsWith('admin'))adminData=state.demo?fakeAdmin():await api('/admin/overview');state.page=p;state.filter='all';state.query='';render();window.scrollTo(0,0);}catch(e){toast(e.message);}};
render=function(){ensureStudio();if(!canPage(state.page)||state.page.startsWith('admin')&&!isAdmin())state.page='profile';const d=state.data,unread=d.notifications.filter(n=>!n.read_at).length;document.title=`${titleMap[state.page]} · Repol Studio`;const mainNav=[...nav,['contacts','users','مخاطب‌ها'],['templates','spark','قالب‌های آماده']].filter(([p])=>canPage(p));const accountNav=[['billing','crown','اشتراک من'],['wallet','wallet','کیف پول'],['notifications','bell','اعلان‌ها'],['profile','user','پروفایل من']];const adminNav=[['admin','shield','نمای مدیریت'],['adminUsers','users','کاربران و دسترسی‌ها'],['adminOrders','card','سفارش‌ها و پرداخت'],['adminNotices','megaphone','مرکز انتشار'],['adminBusiness','wallet','فروش و کیف پول'],['adminAudit','clock','تاریخچهٔ مدیریت']];const navButtons=items=>items.map(([p,i,t])=>`<button data-page="${p}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='notifications'&&unread?`<b class="nav-count">${fa(unread)}</b>`:''}</button>`).join('');
$('#app').innerHTML=`<div class="layout studio-layout"><button class="mobile-backdrop" aria-label="بستن منو" data-studio="close-menu"></button><aside class="sidebar">${brand()}<div class="workspace-box"><div class="workspace-avatar">${icon(isAdmin()?'crown':'spark')}</div><div><strong>${esc(d.settings.workspace)}</strong><small>${isAdmin()?'مدیریت اصلی':'فضای شخصی'}</small></div><span class="workspace-dot"></span></div><div class="nav-scroll"><div class="nav-title">استودیوی گفتگو</div><nav class="nav">${navButtons(mainNav)}</nav><div class="nav-divider"></div><div class="nav-title">حساب و امکانات</div><nav class="nav">${navButtons(accountNav)}${canPage('connections')?navButtons([['connections','plug','اتصال‌ها']]):''}${navButtons([['settings','settings','تنظیمات']])}</nav>${isAdmin()?`<div class="admin-nav-title">${icon('shield')}مدیریت اصلی<span>ADMIN</span></div><nav class="nav admin-nav">${navButtons(adminNav)}</nav>`:''}</div><div class="sidebar-bottom"><button class="mini-sub" data-page="billing"><div>${icon('crown')}<strong>${isAdmin()?'دسترسی مدیریت':d.subscription.daysRemaining?fa(d.subscription.daysRemaining)+' روز باقی‌مانده':'فضای آزمایشی شما'}</strong></div><span>${isAdmin()?'کنترل کامل فضای کار':'مشاهده و تمدید اشتراک'}${icon('arrow')}</span></button><div class="profile"><button class="avatar avatar-${esc(d.owner.avatar)}" data-page="profile" aria-label="پروفایل من">${esc(d.owner.name.charAt(0))}</button><button class="profile-name" data-page="profile"><strong>${esc(d.owner.name)}</strong><small>${isAdmin()?'مدیریت اصلی':'حساب کاربری'}</small></button><button data-action="logout" aria-label="خروج از پنل">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="باز کردن منو">${icon('menu')}</button><span>${isAdmin()&&state.page.startsWith('admin')?'مرکز کنترل':'فضای کار'}</span>${icon('chevron')}<strong>${titleMap[state.page]}</strong></div><div class="top-tools"><button class="search" data-action="search" aria-label="جستجو در پنل">${icon('search')}<span>جستجو در استودیو...</span><kbd>Ctrl K</kbd></button><button class="icon-btn theme-toggle" data-studio="theme" aria-label="تغییر تم">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-studio="sync" aria-label="بررسی به‌روزرسانی">${icon('refresh')}</button><button class="icon-btn notification-trigger" data-page="notifications" aria-label="مرکز اعلان‌ها">${icon('bell')}${unread?'<i></i>':''}</button><button class="avatar avatar-${esc(d.owner.avatar)}" data-page="profile" aria-label="پروفایل من">${esc(d.owner.name.charAt(0))}</button></div></header>${state.demo?`<div class="demo-bar"><span><i class="dot"></i>استودیوی نمایشی · هیچ پرداخت یا پیام واقعی انجام نمی‌شود</span><div><button data-studio="demo-role">${isAdmin()?'دیدن پنل کاربر':'دیدن مدیریت اصلی'}</button><button data-action="logout">ورود / ثبت‌نام</button></div></div>`:''}<div class="content" id="page-content">${pageContent()}<footer class="footer"><span><i class="dot"></i> REPol STUDIO <b>v2.0</b></span><span>ساخته‌شده برای ارتباط‌های ماندگار ${icon('heart')}</span></footer></div><nav class="bottom-nav" aria-label="منوی موبایل">${navButtons([['dashboard','grid','خانه'],['rules','flow','سناریو'],['notifications','bell','اعلان'],['wallet','wallet','کیف پول'],[isAdmin()?'admin':'profile',isAdmin()?'shield':'user',isAdmin()?'مدیریت':'پروفایل']].filter(([p])=>canPage(p)))}</nav></main></div>`;bind();};
pageContent=function(){const d=state.data;switch(state.page){case'profile':return profilePage();case'wallet':return walletPage();case'billing':return billingPage();case'notifications':return notificationsPage();case'contacts':return contactsPage();case'templates':return templatesPage();case'admin':case'adminUsers':case'adminOrders':case'adminNotices':case'adminBusiness':case'adminAudit':return adminPage();case'settings':return preferencesPage();default:return originalPage();}};
function sectionIntro(kicker,title,sub,actions=''){return `<div class="studio-page-head"><div><div class="eyeline"><i></i>${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function paneTitle(title,sub='',button=''){return `<div class="card-head table-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${button}</div>`;}
function statusPill(status){return `<span class="chip ${status==='approved'||status==='active'?'green':status==='rejected'||status==='suspended'?'rose':'orange'}"><i class="dot"></i>${({approved:'تأیید شده',active:'فعال',pending:'در انتظار بررسی',rejected:'رد شده',suspended:'غیرفعال'})[status]||esc(status)}</span>`;}
function profilePage(){const u=state.data.owner;return `${sectionIntro('YOUR IDENTITY','این فضا، امضای تو را دارد.','اطلاعاتت را کامل کن؛ تجربهٔ ریپل را به سلیقهٔ خودت بچین.')}<section class="identity-banner"><div class="identity-orb"></div><div class="avatar avatar-xl avatar-${esc(u.avatar)}">${esc(u.name.charAt(0))}</div><div><span class="chip glass">${icon(isAdmin()?'crown':'user')}${isAdmin()?'مدیر اصلی':'عضو استودیو'}</span><h2>${esc(u.name)}</h2><p dir="ltr">${esc(u.email)}</p></div><div class="identity-stat"><strong>${isAdmin()?'∞':fa(state.data.subscription.daysRemaining)}</strong><span>${isAdmin()?'دسترسی مدیریت':'روز از اشتراک'}</span></div></section><div class="settings-grid"><form class="card settings-card" id="profile-form"><h2>اطلاعات شخصی</h2><div class="form-grid"><div><label for="p-name">نام و نام خانوادگی</label><input id="p-name" name="name" value="${esc(u.name)}" required maxlength="60"></div><div><label for="p-company">کسب‌وکار</label><input id="p-company" name="company" value="${esc(u.company)}" maxlength="100" placeholder="نام برند شما"></div></div><label for="p-phone">شماره موبایل <span class="chip purple">ورود پیامکی به‌زودی</span></label><input class="ltr" id="p-phone" name="phone" value="${esc(u.phone)}" placeholder="+98912…" inputmode="tel" maxlength="20"><p class="hint">اختیاری؛ برای تکمیل پروفایل. تأیید پیامکی هنوز فعال نیست.</p><label for="p-bio">کمی دربارهٔ تو</label><textarea id="p-bio" name="bio" maxlength="300" placeholder="چه چیزی می‌سازی؟">${esc(u.bio)}</textarea><label>رنگ نشان پروفایل</label><div class="avatar-options">${['violet','mint','rose','amber','blue'].map(c=>`<label class="avatar-option avatar-${c}"><input type="radio" name="avatar" value="${c}" ${u.avatar===c?'checked':''}><span>${u.avatar===c?icon('check'):''}</span></label>`).join('')}</div><button class="btn primary" type="submit">ذخیرهٔ پروفایل${icon('check')}</button><div id="profile-error"></div></form><section class="card settings-card"><h2>ورود و امنیت</h2><div class="security-orbit">${icon('shield')}</div><div class="settings-row"><span>ایمیل حساب</span><strong class="ltr profile-email">${esc(u.email)}</strong></div><div class="settings-row"><span>ورود با Google</span><span class="chip purple">به‌زودی</span></div><div class="settings-row"><span>ورود با Facebook</span><span class="chip purple">به‌زودی</span></div><div class="settings-row"><span>ورود با موبایل</span><span class="chip purple">به‌زودی</span></div><p class="security-info">ایمیل ورود از این فرم تغییر نمی‌کند. با تغییر رمز، نشست‌های قبلی بسته می‌شوند.</p><button class="btn full" data-studio="password">${icon('lock')}تغییر رمز عبور</button></section></div>`;}
function preferencesPage(){return `${sectionIntro('MAKE IT YOURS','با سلیقهٔ خودت کار کن.','ظاهر، حرکت‌ها و فضای کار را همان‌طور که دوست داری تنظیم کن.')}<div class="settings-grid"><section class="card settings-card"><h2>ظاهر استودیو</h2><div class="theme-cards">${[['light','sun','روشن'],['dark','moon','تاریک'],['system','globe','همراه دستگاه']].map(([id,i,t])=>`<button class="theme-choice ${state.data.settings.theme===id?'selected':''}" data-theme="${id}"><span class="theme-preview theme-${id}"><i></i><i></i><i></i></span><span>${icon(i)}${t}</span></button>`).join('')}</div><div class="settings-row"><div><strong>حرکت‌های نرم</strong><p class="hint">جابجایی‌ها و جزئیات متحرک رابط</p></div><button role="switch" aria-checked="${state.data.settings.motion}" class="switch ${state.data.settings.motion?'on':''}" data-studio="motion" aria-label="حرکت‌های نرم"></button></div><div class="settings-row"><div><strong>نمای فشرده</strong><p class="hint">ردیف‌های بیشتر، فاصله‌های کمتر</p></div><button role="switch" aria-checked="${!!state.data.settings.compact}" class="switch ${state.data.settings.compact?'on':''}" data-studio="compact" aria-label="نمای فشرده"></button></div></section><form class="card settings-card" id="settings-form"><h2>فضای کار</h2><label for="workspace">نام فضای کار</label><input id="workspace" name="workspace" required value="${esc(state.data.settings.workspace)}" maxlength="80"><div class="settings-row"><span>نسخهٔ فعلی</span><strong>Repol Studio 2.0</strong></div><div class="settings-row"><span>محیط اجرا</span><span class="chip purple">${state.demo?'نمایشی':'محلی'}</span></div><button class="btn primary" type="submit">ذخیرهٔ تغییرات${icon('check')}</button><button class="btn" type="button" data-studio="sync">${icon('refresh')}همگام‌سازی</button></form></div>`;}
function notificationsPage(){const list=state.data.notifications.filter(n=>noticeFilter==='all'||!n.read_at);return `${sectionIntro('YOUR NOTIFICATION CENTER','هیچ اتفاق مهمی جا نمی‌ماند.','خبرهای محصول، وضعیت سفارش‌ها و پیام‌های مدیریت در یک جا.',`<button class="btn" data-studio="read-all">${icon('check')}خواندن همه</button>`)}<div class="toolbar"><div class="filter-tabs"><button class="${noticeFilter==='all'?'active':''}" data-notice-filter="all">همهٔ اعلان‌ها</button><button class="${noticeFilter==='unread'?'active':''}" data-notice-filter="unread">خوانده‌نشده‌ها <span>${fa(state.data.notifications.filter(n=>!n.read_at).length)}</span></button></div><span class="muted micro">به‌روزرسانی خودکار هنگام باز بودن پنل</span></div><div class="notification-list">${list.length?list.map(n=>`<article class="card notice-card ${n.read_at?'':'unread'}"><div class="notice-symbol ${esc(n.type)}">${icon(n.type==='release'?'spark':n.type==='payment'?'wallet':n.type==='success'?'check':'bell')}</div><div class="notice-copy"><div><h3>${esc(n.title)}</h3><time>${when(n.created)}</time></div><p>${esc(n.body)}</p><span class="chip ${n.type==='release'?'purple':'green'}">${({release:'به‌روزرسانی محصول',success:'حساب شما',payment:'پرداخت',warning:'نیاز به توجه'})[n.type]||'اطلاع‌رسانی'}</span></div>${!n.read_at?`<button class="icon-btn" data-read="${esc(n.id)}" aria-label="خواندم: ${esc(n.title)}">${icon('check')}</button>`:''}</article>`).join(''):empty('bell','همه‌چیز را دیده‌ای.','هر خبر تازه‌ای که برسد، همین‌جا پیدایش می‌کنی.')}</div>`;}
function walletPage(){const d=state.data;return `${sectionIntro('YOUR FINANCIAL SPACE','کیف پول، با خیال راحت.','موجودی، گردش اعتبار و وضعیت سفارش‌ها را شفاف ببین.',`<button class="btn primary" data-studio="topup">${icon('plus')}افزایش اعتبار</button>`)}<div class="wallet-layout"><section class="wallet-visual"><div class="wallet-glow"></div><div class="wallet-top">${brand()}<span>STUDIO WALLET</span></div><p>اعتبار قابل استفاده</p><div class="wallet-amount">${money(d.wallet.balance)}<span>تومان</span></div><div class="wallet-bottom"><span>${esc(d.owner.name)}</span><span>IRR • ${state.demo?'DEMO':'PERSONAL'}</span></div></section><section class="card wallet-summary"><h2>یک مسیر روشن برای پرداخت</h2><div>${icon('card')}<span><strong>پرداخت ریالی</strong><small>کد سفارش + پشتیبانی تلگرام</small></span></div><div>${icon('tron')}<span><strong>TRX روی شبکهٔ TRON</strong><small>تأیید تراکنش قطعی و تمدید خودکار</small></span></div><div>${icon('shield')}<span><strong>ثبت گردش اعتبار</strong><small>هر تغییر موجودی با یک سابقهٔ مشخص</small></span></div></section></div><section class="card">${paneTitle('گردش اعتبار','مبالغ این بخش به تومان نمایش داده می‌شوند')}<div class="table-wrap"><table><thead><tr><th>شرح</th><th>نوع</th><th>مبلغ</th><th>تاریخ</th></tr></thead><tbody>${d.wallet.ledger.map(l=>`<tr><td>${esc(l.reason)}</td><td><span class="chip ${l.amount>0?'green':'purple'}">${l.amount>0?'افزایش':'برداشت'}</span></td><td>${money(Math.abs(l.amount))} تومان</td><td>${when(l.created)}</td></tr>`).join('')}</tbody></table></div>${!d.wallet.ledger.length?empty('wallet','گردش اعتبارت از اینجا شروع می‌شود.','پس از تأیید اولین شارژ یا خرید، جزئیات اینجا ثبت می‌شود.'):''}</section>`;}
function priceCards(publicMode=false){const b=publicMode?(catalog||defaultBusiness):state.data.business;return `<div class="pricing-grid">${b.plans.map((p,i)=>`<article class="plan-card ${i===1?'featured':''}">${i===1?'<div class="popular-tag">برای یک مسیر جدی‌تر ✦</div>':''}<div class="plan-symbol">${icon(['spark','bolt','crown'][i])}</div><span class="plan-duration">${fa(p.days)} روز</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="plan-price">${money(p.priceIRR)}<span>تومان / ${fa(p.days)} روز</span></div><ul>${p.features.map(f=>`<li>${icon('check')}${esc(f)}</li>`).join('')}</ul><button class="btn ${i===1?'primary':''} full" ${publicMode?'data-public-plan':'data-plan'}="${p.id}">${publicMode?'اول تجربه کن':'انتخاب این اشتراک'}${icon('arrow')}</button><small>تمدید به روزهای باقی‌مانده اضافه می‌شود</small></article>`).join('')}</div>`;}
function ordersTable(orders,adminMode=false){return orders.length?`<div class="table-wrap"><table><thead><tr><th>سفارش</th>${adminMode?'<th>کاربر</th>':''}<th>مبلغ</th><th>روش</th><th>وضعیت</th><th>جزئیات</th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong class="order-code">${esc(o.code)}</strong><small class="cell-note">${esc(o.snapshot?.planName||o.kind)}</small></td>${adminMode?`<td>${esc(o.name)}<small class="cell-note">${esc(o.email)}</small></td>`:''}<td>${o.currency==='TRX'?Number(o.amount/1e6).toLocaleString('en-US',{maximumFractionDigits:6})+' TRX':money(o.amount)+' تومان'}</td><td>${({rial:'ریالی',crypto:'TRON',wallet:'کیف پول'})[o.method]}</td><td>${statusPill(o.status)}</td><td><button class="btn tiny" ${adminMode?'data-review':'data-invoice'}="${esc(o.id)}">${adminMode?'بررسی':'پیش‌فاکتور'}${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('card','هنوز سفارشی ثبت نشده.','بعد از انتخاب اشتراک، پیش‌فاکتور و وضعیت پرداخت اینجا ظاهر می‌شوند.');}
function billingPage(){const d=state.data;return `${sectionIntro('GROW AT YOUR OWN PACE','اول دوستش داشته باش؛ بعد انتخاب کن.','اشتراک شفاف، تمدید بدون از دست دادن روزهای قبلی.')}<div class="subscription-strip"><div class="sub-icon">${icon('crown')}</div><div><strong>${isAdmin()?'شما مدیریت اصلی هستید':d.subscription.active?'اشتراک شما فعال است':'در حال تجربهٔ فضای کار'}</strong><p>${isAdmin()?'برای مدیریت پنل محدودیت اشتراک نداری.':d.subscription.active?'تاریخ پایان: '+when(d.subscription.expires):'پیش از خرید، سناریوها و محیط را بررسی کن.'}</p></div><div class="days-counter"><strong>${isAdmin()?'∞':fa(d.subscription.daysRemaining)}</strong><span>روز باقی‌مانده</span></div></div>${!d.business.salesEnabled?'<div class="note-banner">'+icon('info')+'نسخهٔ پیش‌عرضه: قیمت‌ها مشخص‌اند، اما دریافت وجه تا فعال‌سازی فروش توسط مدیریت بسته است.</div>':''}${priceCards()}<div class="price-footnote">ماهانه ۸۴۹ هزار تومان؛ ۵۰ هزار تومان کمتر از پلن پایهٔ نوین‌هاب در بررسی ۳۰ سپتامبر ۲۰۲۶. امکانات دو سرویس یکسان فرض نشده‌اند.</div><section class="card">${paneTitle('سفارش‌های من','پیش‌فاکتور، پرداخت و وضعیت بررسی')}${ordersTable(d.orders)}</section>`;}
function contactsPage(){return `${sectionIntro('PEOPLE, NOT JUST NUMBERS','آدم‌ها را بهتر بشناس.','نام، برچسب و یادداشت؛ جزئیات کوچکی برای ارتباط‌های بهتر.',`<button class="btn primary" data-studio="add-contact">${icon('plus')}مخاطب جدید</button>`)}<section class="card">${paneTitle('دفتر مخاطب‌ها',fa(state.data.contacts.length)+' مخاطب ثبت‌شده')}<div class="table-wrap"><table><thead><tr><th>مخاطب</th><th>شناسه</th><th>برچسب</th><th>یادداشت</th></tr></thead><tbody>${state.data.contacts.map(c=>`<tr><td><div class="title-cell"><div class="avatar">${esc(c.name.charAt(0))}</div>${esc(c.name)}</div></td><td dir="ltr">${esc(c.handle)}</td><td><span class="chip purple">${esc(c.tag||'بدون برچسب')}</span></td><td class="wrap-cell">${esc(c.note)}</td></tr>`).join('')}</tbody></table></div>${!state.data.contacts.length?empty('users','اولین مخاطبت را اضافه کن.','در این نسخه مخاطب‌ها دستی ثبت می‌شوند؛ همگام‌سازی با اینستاگرام هنوز متصل نیست.'):''}</section>`;}
const starterTemplates=[{name:'استقبال گرم',category:'خوش‌آمدگویی',text:'سلام! خوشحالم که اینجایی 🌱 دوست داری دربارهٔ کدام بخش بیشتر بدانی؟'},{name:'راهنمای خرید',category:'فروش',text:'سلام! برای راهنمایی دقیق‌تر، نام محصولی که دوست داری را بفرست.'},{name:'ارسال آموزش',category:'آموزش',text:'سلام! ممنون از علاقه‌ات به یادگیری. اینجا لینک آموزش را قرار بده.'},{name:'پیگیری دوستانه',category:'پشتیبانی',text:'سلام! خواستم مطمئن شوم پاسخ سؤال خودت را گرفتی. کمکی از دستم برمی‌آید؟'}];
function templatesPage(){return `${sectionIntro('A LITTLE INSPIRATION','از یک پاسخ خوب شروع کن.','قالب‌ها را شخصی‌سازی کن و به سناریوی خودت تبدیل کن.',`<button class="btn primary" data-studio="add-template">${icon('plus')}قالب اختصاصی</button>`)}<div class="template-grid">${[...starterTemplates,...state.data.templates].map((t,i)=>`<article class="card template-card"><div><span class="template-icon">${icon(['heart','card','book','message'][i%4])}</span><span class="chip purple">${esc(t.category||'اختصاصی')}</span></div><h3>${esc(t.name)}</h3><p>${esc(t.text)}</p><button class="btn full" data-template-index="${i}">استفاده در سناریو${icon('arrow')}</button></article>`).join('')}</div>`;}
function adminPage(){const a=adminData||fakeAdmin();if(state.page==='admin')return adminOverview(a);if(state.page==='adminUsers')return `${sectionIntro('PEOPLE & PERMISSIONS','هر کاربر، یک فضای مستقل.','دسترسی منوها، وضعیت حساب و مدت اشتراک را مدیریت کن.')}<div class="toolbar"><div class="chip purple">${fa(a.users.length)} حساب کاربری</div><div class="search-field">${icon('search')}<input id="users-query" placeholder="نام یا ایمیل کاربر…" aria-label="جستجوی کاربران" value="${esc(userQuery)}"></div></div><section class="card" id="admin-users-table">${userTable(a.users)}</section>`;
if(state.page==='adminOrders')return `${sectionIntro('PAYMENT OPERATIONS','از سفارش تا فعال‌سازی.','پرداخت ریالی با بررسی مدیر؛ TRX با تأیید قطعی شبکه.')}<div class="filter-tabs admin-filter">${[['all','همه'],['pending','در انتظار'],['approved','تأییدشده'],['rejected','ردشده']].map(([k,t])=>`<button data-order-filter="${k}" class="${orderFilter===k?'active':''}">${t}</button>`).join('')}</div><section class="card">${ordersTable(a.orders.filter(o=>orderFilter==='all'||o.status===orderFilter),true)}</section>`;
if(state.page==='adminNotices')return noticeComposer(a);if(state.page==='adminBusiness')return businessPage(a);return `${sectionIntro('A CLEAR AUDIT TRAIL','هر تغییر، یک رد روشن.','ثبت عملیات مدیریت برای پیگیری دسترسی‌ها، اشتراک و پرداخت‌ها.')}<section class="card">${paneTitle('تاریخچهٔ عملیات','آخرین ۱۰۰ رویداد مدیریتی')}<div class="audit-list">${a.audit.map(e=>`<div class="audit-row"><div>${icon('shield')}</div><section><strong>${esc(actionLabel(e.action))}</strong><p>${esc(e.actorName)} · ${esc(e.target||'فضای کار')}</p></section><time>${when(e.created)}</time></div>`).join('')}</div></section>`;}
function actionLabel(a){return ({'account.created':'ساخت حساب','user.access.updated':'تغییر دسترسی کاربر','subscription.granted':'افزایش روزهای اشتراک','order.approved':'تأیید پرداخت','order.rejected':'رد پرداخت','order.created':'ثبت سفارش','announcement.sent':'انتشار اعلان','business.updated':'تغییر تنظیمات فروش','profile.updated':'ویرایش پروفایل','password.changed':'تغییر رمز عبور'})[a]||a;}
function adminOverview(a){const users=a.users.filter(u=>u.role!=='admin'),paid=a.orders.filter(o=>o.status==='approved'&&o.currency==='IRR');return `${sectionIntro('REPOL COMMAND CENTER','اینجا همه‌چیز در کنترل توست.','یک نمای روشن از کاربران، اشتراک‌ها و اتفاق‌های مهم استودیو.',`<button class="btn primary" data-page="adminNotices">${icon('megaphone')}اعلان جدید</button>`)}<section class="command-hero"><div class="command-grid"></div><div><span class="chip glass">${icon('shield')}مدیریت اصلی · دسترسی کامل</span><h2>یک استودیو.<br>هزار فرصت برای رشد<span>✦</span></h2><p>از تجربهٔ اولین ورود تا تمدید اشتراک؛ همهٔ مسیر را ببین.</p><div class="command-actions"><button class="btn" data-page="adminUsers">مدیریت کاربران${icon('arrow')}</button><button class="text-link" data-page="adminBusiness">تنظیمات کسب‌وکار</button></div></div><div class="command-art" aria-hidden="true"><div class="radar-ring"></div><div class="radar-ring two"></div><div class="radar-core">${icon('crown')}</div><div class="radar-node one">${icon('users')}</div><div class="radar-node two">${icon('wallet')}</div><div class="radar-node three">${icon('megaphone')}</div></div></section><div class="stats admin-stats">${[['users','کاربران ثبت‌شده',fa(users.length),'فضاهای مستقل'],['crown','اشتراک فعال',fa(users.filter(u=>u.daysRemaining>0).length),'بر اساس اعتبار زمانی'],['card','سفارش در انتظار',fa(a.orders.filter(o=>o.status==='pending').length),'نیازمند بررسی'],['wallet','دریافت تأییدشده',money(paid.reduce((s,o)=>s+o.amount,0)),'تومان · سفارش ریالی']].map(([i,t,n,b])=>`<article class="stat"><div class="stat-top"><span>${t}</span><div class="stat-icon">${icon(i)}</div></div><div class="stat-value">${n}</div><div class="stat-bottom">${b}</div></article>`).join('')}</div><div class="admin-overview-grid"><section class="card">${paneTitle('کاربران تازه','هر حساب، شروع یک ارتباط',`<button class="text-link" data-page="adminUsers">همهٔ کاربران${icon('chevron')}</button>`)}${userTable(a.users.slice(0,4),true)}</section><section class="card quick-controls">${paneTitle('میانبرهای مدیریت','برای کارهای مهم، مسیر کوتاه‌تر')}<button data-page="adminOrders"><span class="quick-icon">${icon('card')}</span><span><strong>بررسی پرداخت‌ها</strong><small>${fa(a.orders.filter(o=>o.status==='pending').length)} سفارش در انتظار</small></span>${icon('chevron')}</button><button data-page="adminNotices"><span class="quick-icon">${icon('megaphone')}</span><span><strong>یک خبر برای همه</strong><small>اعلان عمومی و به‌روزرسانی</small></span>${icon('chevron')}</button><button data-page="adminBusiness"><span class="quick-icon">${icon('tron')}</span><span><strong>کیف پول مدیریت</strong><small>موجودی و تنظیمات TRON</small></span>${icon('chevron')}</button><div class="ops-status"><i class="dot"></i>${a.chainStatus?.error?'بررسی شبکه نیاز به توجه دارد':'مرکز مدیریت آمادهٔ استفاده است'}<small>${state.demo?'اطلاعات این صفحه نمایشی است':'اتصال اینستاگرام هنوز فعال نیست'}</small></div></section></div>`;}
function userTable(users,compact=false){const filtered=users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(userQuery.toLowerCase()));return `<div class="table-wrap"><table><thead><tr><th>کاربر</th><th>وضعیت</th><th>اشتراک</th>${compact?'':'<th>سناریو</th>'}<th>مدیریت</th></tr></thead><tbody>${filtered.map(u=>`<tr><td><div class="title-cell"><div class="avatar avatar-${esc(u.avatar||'violet')}">${esc(u.name.charAt(0))}</div><div>${esc(u.name)}<small>${esc(u.email)}</small></div></div></td><td>${statusPill(u.status||'active')}</td><td>${u.role==='admin'?'<span class="chip purple">مدیر اصلی</span>':u.daysRemaining?`<span class="expiry">${fa(u.daysRemaining)} روز</span>`:'<span class="muted">بدون اشتراک</span>'}</td>${compact?'':`<td>${fa(u.ruleCount||0)}</td>`}<td><button class="icon-btn" data-user="${esc(u.id)}" aria-label="مدیریت ${esc(u.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>${!filtered.length?empty('users','کاربری پیدا نشد.','عبارت جستجو را تغییر بده.'):''}`;}
function noticeComposer(a){return `${sectionIntro('ONE MESSAGE, REAL CONNECTION','صدایت به آدم درست برسد.','اعلان اختصاصی، خبر عمومی یا معرفی نسخهٔ جدید محصول.')}<div class="settings-grid"><form id="announcement-form" class="card settings-card"><h2>یک اعلان تازه</h2><label for="notice-target">مخاطب</label><select id="notice-target" name="userId"><option value="">همهٔ کاربران فعلی</option>${a.users.map(u=>`<option value="${esc(u.id)}">${esc(u.name)} · ${esc(u.email)}</option>`).join('')}</select><div class="form-grid"><div><label for="notice-type">نوع پیام</label><select id="notice-type" name="type"><option value="info">اطلاع‌رسانی</option><option value="release">به‌روزرسانی سراسری</option><option value="success">خبر خوب</option><option value="warning">نیاز به توجه</option></select></div><div><label for="notice-title">عنوان</label><input id="notice-title" name="title" maxlength="120" required placeholder="یک خبر خوب داریم…"></div></div><label for="notice-body">متن پیام</label><textarea id="notice-body" name="body" required maxlength="2000" placeholder="پیامت را واضح و صمیمی بنویس…"></textarea><p class="hint">اعلان داخل پنل نمایش داده می‌شود؛ ایمیل یا تلگرام ارسال نمی‌شود.</p><button class="btn primary" type="submit">${icon('megaphone')}انتشار اعلان</button><div id="notice-error"></div></form><section class="card settings-card"><div class="eyeline">LIVE PREVIEW</div><h2>از نگاه کاربر</h2><div class="notice-preview"><div class="notice-symbol release">${icon('spark')}</div><span class="chip purple">اعلان مدیریت</span><h3 id="notice-preview-title">یک خبر خوب داریم…</h3><p id="notice-preview-body">متنی که می‌نویسی، اینجا جان می‌گیرد.</p><small>همین حالا · ریپل استودیو</small></div></section></div><section class="card history-card">${paneTitle('خبرهایی که منتشر کردی','وضعیت خواندن اعلان‌های تحویل‌شده')}<div class="table-wrap"><table><thead><tr><th>عنوان</th><th>مخاطب</th><th>خوانده‌شده</th><th>تاریخ</th></tr></thead><tbody>${a.announcements.map(n=>`<tr><td>${esc(n.title)}</td><td>${fa(n.recipients)} نفر</td><td>${fa(n.reads)} نفر</td><td>${when(n.created)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function businessPage(a){const b=a.business;return `${sectionIntro('BUSINESS SETTINGS','پشت هر پرداخت، یک تنظیم دقیق.','تعرفه‌ها، مقصد TRX و وضعیت دریافت سفارش را اینجا کنترل کن.')}<div class="wallet-layout"><section class="wallet-visual admin-wallet"><div class="wallet-glow"></div><div class="wallet-top">${icon('tron')}<span>TRON MAINNET · TRX</span></div><p>موجودی کیف پول مدیریت</p><div class="wallet-amount" id="chain-balance">—<span>TRX</span></div><div class="wallet-address">${esc(b.cryptoAddress)}</div><button class="btn glass-btn" data-studio="chain-balance">${icon('refresh')}استعلام موجودی واقعی</button><small id="chain-balance-time">فقط خواندن موجودی؛ دسترسی برداشت وجود ندارد.</small></section><section class="card wallet-summary"><h2>تأیید پرداخت، بدون حدس</h2><div>${icon('check')}<span><strong>تراکنش قطعی شبکه</strong><small>تطبیق مبلغ دقیق، مقصد و مهلت سفارش</small></span></div><div>${icon('shield')}<span><strong>فقط یک بار</strong><small>هر تراکنش فقط یک اشتراک را فعال می‌کند</small></span></div><div>${icon('refresh')}<span><strong>بررسی دوره‌ای</strong><small>هر ۶۰ ثانیه، هنگام اجرای سرور</small></span></div></section></div><form class="card settings-card" id="business-form"><h2>تنظیمات فروش</h2><div class="form-grid"><div><label for="crypto-address">آدرس دریافت TRX</label><input dir="ltr" id="crypto-address" name="cryptoAddress" value="${esc(b.cryptoAddress)}" required></div><div><label for="crypto-network">شبکه و ارز</label><input id="crypto-network" value="TRON Mainnet — TRX" readonly></div></div><div class="business-switches"><label class="check-label"><input type="checkbox" name="salesEnabled" ${b.salesEnabled?'checked':''}>پذیرش سفارش و فروش فعال باشد</label><label class="check-label"><input type="checkbox" name="cryptoEnabled" ${b.cryptoEnabled?'checked':''}>پرداخت TRX و بررسی خودکار شبکه فعال باشد</label></div><div class="note-banner">${icon('info')}نرخ TRX هنگام صدور سفارش از بازار نوبیتکس دریافت و برای همان فاکتور ثابت می‌شود. اگر نرخ معتبر دریافت نشود، فاکتور ارزی صادر نمی‌شود.</div><div class="plan-config-grid">${b.plans.map(p=>`<fieldset><legend>${esc(p.name)}</legend><label>نام پلن<input name="name-${p.id}" value="${esc(p.name)}" required></label><label>مدت (روز)<input type="number" name="days-${p.id}" min="1" max="3650" value="${p.days}" required></label><label>قیمت (تومان)<input type="number" name="price-${p.id}" min="0" value="${p.priceIRR/10}" required></label></fieldset>`).join('')}</div><p class="hint">فروش واقعی پیش از تکمیل اتصال‌ها و تست پرداخت فعال نشده است. آیدی پشتیبانی ریالی: @fesghli</p><button class="btn primary" type="submit">${icon('check')}ذخیرهٔ تنظیمات</button><div id="business-error"></div></form>`;}
bind=function(){originalBind();$$('[data-studio]').forEach(b=>b.onclick=()=>studioAction(b.dataset.studio));$$('[data-theme]').forEach(b=>b.onclick=()=>savePreferences({theme:b.dataset.theme}));$$('[data-notice-filter]').forEach(b=>b.onclick=()=>{noticeFilter=b.dataset.noticeFilter;render();});$$('[data-read]').forEach(b=>b.onclick=()=>readNotice(b.dataset.read));$$('[data-plan]').forEach(b=>b.onclick=()=>checkout(b.dataset.plan));$$('[data-invoice]').forEach(b=>b.onclick=()=>invoice(state.data.orders.find(o=>o.id===b.dataset.invoice)));$$('[data-user]').forEach(b=>b.onclick=()=>userDrawer(b.dataset.user));$$('[data-review]').forEach(b=>b.onclick=()=>reviewOrder(b.dataset.review));$$('[data-order-filter]').forEach(b=>b.onclick=()=>{orderFilter=b.dataset.orderFilter;render();});$$('[data-template-index]').forEach(b=>b.onclick=()=>{const t=[...starterTemplates,...state.data.templates][Number(b.dataset.templateIndex)];ruleDrawer({name:t.name,keywords:[],response:t.text,enabled:false,trigger:'dm'});});$('#users-query')?.addEventListener('input',e=>{userQuery=e.target.value;$('#admin-users-table').innerHTML=userTable(adminData.users);$$('[data-user]').forEach(b=>b.onclick=()=>userDrawer(b.dataset.user));});$('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));await withForm(e.target,async()=>{if(state.demo){state.data.owner={...state.data.owner,...data};demoSave();}else state.data.owner=await api('/profile',{method:'PUT',body:JSON.stringify(data)});render();toast('پروفایلت به‌روز شد.');},'#profile-error');});$('#announcement-form')?.addEventListener('submit',sendAnnouncement);$('#notice-title')?.addEventListener('input',e=>$('#notice-preview-title').textContent=e.target.value||'یک خبر خوب داریم…');$('#notice-body')?.addEventListener('input',e=>$('#notice-preview-body').textContent=e.target.value||'متنی که می‌نویسی، اینجا جان می‌گیرد.');$('#business-form')?.addEventListener('submit',saveBusiness);};
async function withForm(form,fn,errorSelector){const btn=$('button[type=submit]',form);if(btn)btn.disabled=true;try{await fn();}catch(e){if(errorSelector&&$(errorSelector))err($(errorSelector),e);else toast(e.message);}finally{if(btn)btn.disabled=false;}}
action=async function(a){if(a==='menu'){document.body.classList.toggle('menu-open');$('.sidebar')?.classList.toggle('open');return;}if(a==='logout'){adminData=null;demoRole='admin';document.body.classList.remove('menu-open');}await originalAction(a);};
async function savePreferences(changes){const previous={...state.data.settings};state.data.settings={...previous,...changes};applyTheme();render();try{if(state.demo)demoSave();else state.data.settings=await api('/settings',{method:'PUT',body:JSON.stringify(changes)});if(changes.theme)localStorage.setItem('repol-theme',changes.theme);applyTheme();}catch(e){state.data.settings=previous;applyTheme();render();toast('تنظیمات ذخیره نشد: '+e.message);}}
async function studioAction(a){if(a==='theme')return savePreferences({theme:document.documentElement.dataset.theme==='dark'?'light':'dark'});if(a==='motion')return savePreferences({motion:!state.data.settings.motion});if(a==='compact')return savePreferences({compact:!state.data.settings.compact});if(a==='close-menu'){document.body.classList.remove('menu-open');$('.sidebar')?.classList.remove('open');}if(a==='demo-role'){demoRole=isAdmin()?'user':'admin';state.data.owner.role=demoRole;state.page='dashboard';render();toast(isAdmin()?'پیش‌نمایش مدیریت اصلی':'پیش‌نمایش پنل کاربر عادی');}if(a==='read-all')return readNotice();if(a==='password')return passwordDialog();if(a==='add-contact')return resourceDialog('contact');if(a==='add-template')return resourceDialog('template');if(a==='topup')return checkout(null,true);if(a==='chain-balance'){if(state.demo)return toast('موجودی واقعی در حساب مدیر و پس از اتصال شبکه قابل استعلام است.');const target=$('#chain-balance');target.textContent='در حال استعلام…';try{const d=await api('/admin/wallet-balance');target.innerHTML=`${Number(d.balanceSun/1e6).toLocaleString('en-US',{maximumFractionDigits:6})}<span>TRX</span>`;$('#chain-balance-time').textContent='آخرین بررسی: '+new Date(d.checkedAt).toLocaleString('fa-IR');}catch(e){target.innerHTML='—<span>TRX</span>';toast(e.message);}}if(a==='sync'){try{if(!state.demo){state.data=await api('/data');if(state.page.startsWith('admin'))adminData=await api('/admin/overview');}render();toast('اطلاعات به‌روز شد؛ نسخهٔ فعلی ۲.۰ است.');}catch(e){toast(e.message);}}}
async function readNotice(id){try{if(!state.demo)await api('/notifications/read',{method:'POST',body:JSON.stringify({id})});state.data.notifications.forEach(n=>{if(!id||n.id===id)n.read_at=Date.now();});if(state.demo)demoSave();render();}catch(e){toast(e.message);}}
function passwordDialog(){dialog(`${dialogHead('رمزی تازه برای حسابت')}<form id="password-form"><label for="pw-old">رمز فعلی</label><input id="pw-old" type="password" name="currentPassword" autocomplete="current-password" required><label for="pw-new">رمز جدید</label><input id="pw-new" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="hint">حداقل ۱۲ کاراکتر. نشست‌های قبلی پس از تغییر رمز بسته می‌شوند.</p><button class="btn primary full" type="submit">ذخیرهٔ رمز جدید</button><div id="pw-error"></div></form>`);$('#password-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{if(state.demo)throw new Error('حساب نمایشی رمز واقعی ندارد. برای تغییر رمز وارد حساب خودت شو.');await api('/auth/password',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeDialog();toast('رمز تغییر کرد و نشست‌های قبلی بسته شدند.');},'#pw-error');};}
function resourceDialog(kind){const contact=kind==='contact';dialog(`${dialogHead(contact?'یک مخاطب تازه':'قالبی با لحن خودت')}<form id="resource-form"><label for="r-name">${contact?'نام مخاطب':'نام قالب'}</label><input id="r-name" name="name" maxlength="100" required>${contact?'<label for="r-handle">شناسه اینستاگرام</label><input id="r-handle" name="handle" dir="ltr" maxlength="80" placeholder="username"><label for="r-tag">برچسب</label><input id="r-tag" name="tag" maxlength="40" placeholder="مشتری، علاقه‌مند، پیگیری…"><label for="r-text">یادداشت</label><textarea id="r-text" name="note" maxlength="1000"></textarea>':'<label for="r-category">دسته‌بندی</label><input id="r-category" name="category" maxlength="30" placeholder="فروش، آموزش، پشتیبانی…"><label for="r-text">متن پاسخ</label><textarea id="r-text" name="text" maxlength="2000" required></textarea>'}<button class="btn primary full" type="submit">${icon('check')}ذخیره</button><div id="resource-error"></div></form>`);$('#resource-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{const b=Object.fromEntries(new FormData(e.target));if(state.demo){state.data[contact?'contacts':'templates'].unshift({...b,id:crypto.randomUUID(),created:Date.now()});demoSave();}else{await api(contact?'/contacts':'/templates',{method:'POST',body:JSON.stringify(b)});state.data=await api('/data');}closeDialog();render();toast('اطلاعات ذخیره شد.');},'#resource-error');};}
function checkout(planId,topup=false){const plan=state.data.business.plans.find(p=>p.id===planId);dialog(`${dialogHead(topup?'به کیف پولت اعتبار بده':'یک قدم تا اشتراک تازه','پیش‌فاکتور قبل از پرداخت ساخته می‌شود.')}<form id="checkout-form">${topup?'<label for="topup-amount">مبلغ شارژ (تومان)</label><input id="topup-amount" name="amountToman" type="number" min="1000" max="100000000" value="100000" required>':`<div class="checkout-plan"><span>${icon('crown')}اشتراک ${esc(plan.name)} · ${fa(plan.days)} روز</span><strong>${money(plan.priceIRR)}<small>تومان</small></strong></div>`}<label>روش پرداخت</label><div class="payment-options"><label><input type="radio" name="method" value="rial" checked><span>${icon('card')}<strong>پرداخت ریالی</strong><small>سفارش + هماهنگی در تلگرام</small></span></label>${!topup?`<label><input type="radio" name="method" value="crypto" ${!state.demo&&!state.data.business.cryptoEnabled?'disabled':''}><span>${icon('tron')}<strong>TRX / شبکهٔ TRON</strong><small>${state.data.business.cryptoEnabled||state.demo?'تأیید شبکه و تمدید خودکار':'در انتظار فعال‌سازی'}</small></span></label><label><input type="radio" name="method" value="wallet"><span>${icon('wallet')}<strong>اعتبار کیف پول</strong><small>${money(state.data.wallet.balance)} تومان موجودی</small></span></label>`:''}</div><p class="hint">${state.demo?'این پیش‌فاکتور نمایشی است. هیچ وجهی واریز نکن.':'در روش ریالی، پس از صدور سفارش، کد و آیدی @fesghli نمایش داده می‌شود.'}</p><button class="btn primary full" type="submit">${icon('file')}ساخت پیش‌فاکتور</button><div id="checkout-error"></div></form>`);const requestId=crypto.randomUUID();$('#checkout-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{const fields=Object.fromEntries(new FormData(e.target)),b={kind:topup?'topup':'subscription',planId,method:fields.method,amount:Number(fields.amountToman)*10,requestId};let order;if(state.demo){if(b.method==='wallet'&&state.data.wallet.balance<plan.priceIRR)throw new Error('اعتبار نمایشی کافی نیست. روش ریالی را امتحان کن.');order={id:crypto.randomUUID(),code:'RP-DEMO-'+crypto.randomUUID().slice(0,6).toUpperCase(),user_id:'demo-self',name:state.data.owner.name,email:state.data.owner.email,kind:b.kind,plan_id:planId,days:plan?.days||0,amount:topup?b.amount:plan.priceIRR,currency:'IRR',method:b.method,status:b.method==='wallet'?'approved':'pending',created:Date.now(),expires:Date.now()+1800000,snapshot:{planName:plan?.name||'شارژ اعتبار',support:'fesghli',demo:true},proof:''};if(b.method==='crypto'){order.amount=123456789;order.currency='TRX';}if(b.method==='wallet'){state.data.wallet.balance-=plan.priceIRR;state.data.wallet.ledger.unshift({amount:-plan.priceIRR,reason:'خرید نمایشی اشتراک',created:Date.now()});extendDemoSubscription(state.data.subscription,plan.days,plan.id);}state.data.orders.unshift(order);fakeAdmin().orders.unshift(order);demoSave();}else{const created=await api('/orders',{method:'POST',body:JSON.stringify(b)});state.data=await api('/data');order=state.data.orders.find(o=>o.id===created.id);}closeDialog();render();invoice(order);},'#checkout-error');};}
function invoice(o){if(!o)return;const crypto=o.method==='crypto';dialog(`<div class="invoice"><div class="invoice-top"><span>${brand()}</span><button class="icon-btn" data-close aria-label="بستن">${icon('close')}</button></div><div class="invoice-status">${icon(o.status==='approved'?'check':'file')}</div><div class="eyeline">${state.demo?'DEMO INVOICE':'YOUR ORDER'}</div><h2 id="dialog-title">${o.status==='approved'?'اشتراکت آماده است.':'پیش‌فاکتورت آماده است.'}</h2><p>${state.demo?'نمایشی است؛ هیچ مبلغی واریز نکن.':'کد سفارش را برای پیگیری نگه دار.'}</p><div class="invoice-number"><span>${esc(o.code)}</span><button class="icon-btn" data-copy="${esc(o.code)}" aria-label="کپی کد سفارش">${icon('copy')}</button></div><div class="invoice-details"><div><span>شرح سفارش</span><strong>${esc(o.snapshot?.planName||'اشتراک')}</strong></div><div><span>مدت اعتبار</span><strong>${fa(o.days)} روز</strong></div><div><span>وضعیت</span>${statusPill(o.status)}</div><div class="invoice-total"><span>مبلغ قابل پرداخت</span><strong>${crypto?Number(o.amount/1e6).toFixed(6)+' TRX':money(o.amount)+' تومان'}</strong></div></div>${o.status==='pending'?crypto?`<div class="crypto-invoice"><span class="chip purple">فقط TRX · شبکهٔ TRON</span><p>مبلغ دقیق فاکتور را بدون کم‌کردن کارمزد بفرست. مهلت: ${new Date(o.expires).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</p><div class="code-block">${state.demo?'نسخهٔ نمایشی — آدرس واریز نمایش داده نمی‌شود':esc(o.snapshot.cryptoAddress)}</div><p class="hint">بخش اعشاری برای تشخیص سفارش است. تأیید پس از قطعی شدن تراکنش انجام می‌شود. تراکنش دیرهنگام نیاز به بررسی مدیر دارد.</p><form id="verify-trx"><label for="txid">شناسه تراکنش (TxID)</label><input id="txid" name="txid" dir="ltr" placeholder="64-character transaction hash" maxlength="64" required><button class="btn primary full" type="submit">${icon('refresh')}بررسی تراکنش و فعال‌سازی</button><div id="trx-error"></div></form></div>`:`<div class="rial-invoice"><div class="telegram-orb">${icon('telegram')}</div><h3>کد سفارش را برای ما بفرست.</h3><p>برای هماهنگی پرداخت ریالی، کد بالا را به این آیدی در تلگرام ارسال کن.</p><a class="btn primary full" href="https://t.me/fesghli" target="_blank" rel="noopener noreferrer">@fesghli ${icon('arrow')}</a><form id="proof-form"><label for="proof">شناسه یا توضیح پرداخت (اختیاری)</label><input id="proof" name="proof" value="${esc(o.proof||'')}" maxlength="500" placeholder="برای بررسی سریع‌تر سفارش"><button class="btn full" type="submit">ثبت اطلاعات پرداخت</button></form></div>`:`<div class="success-box">${o.status==='approved'?'این پرداخت ثبت شده و دوباره اعمال نمی‌شود.':esc(o.note||'برای پیگیری با پشتیبانی در تماس باش.')}</div>`}<div class="invoice-foot">${icon('shield')}REPOL STUDIO · ${state.demo?'PREVIEW':'ORDER RECORD'}</div></div>`);bindCopy();$('#proof-form')?.addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const proof=new FormData(e.target).get('proof');if(proof.length<5)throw new Error('حداقل ۵ کاراکتر بنویس.');if(state.demo){o.proof=proof;demoSave();}else await api('/orders/'+o.id+'/proof',{method:'POST',body:JSON.stringify({proof})});toast('اطلاعات برای بررسی ثبت شد.');});});$('#verify-trx')?.addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{if(state.demo)throw new Error('در پیش‌نمایش تراکنش واقعی بررسی نمی‌شود.');await api('/orders/'+o.id+'/verify',{method:'POST',body:JSON.stringify({txid:new FormData(e.target).get('txid')})});state.data=await api('/data');closeDialog();render();invoice(state.data.orders.find(x=>x.id===o.id));},'#trx-error');});}
function bindCopy(){$$('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('کپی شد.');}catch{toast('کپی خودکار ممکن نشد؛ متن را انتخاب و کپی کن.');}});}
function userDrawer(id){const u=adminData.users.find(x=>x.id===id);dialog(`${dialogHead('مدیریت '+esc(u.name),'اطلاعات، دسترسی و اشتراک این حساب')}<div class="user-summary"><div class="avatar avatar-xl avatar-${esc(u.avatar||'violet')}">${esc(u.name.charAt(0))}</div><h3>${esc(u.name)}</h3><p dir="ltr">${esc(u.email)}</p>${statusPill(u.status)}<div><span>${esc(u.phone||'شماره ثبت نشده')}</span><span>${esc(u.company||'کسب‌وکار ثبت نشده')}</span></div></div><div class="user-metrics"><div><strong>${fa(u.daysRemaining)}</strong><span>روز اشتراک</span></div><div><strong>${fa(u.ruleCount||0)}</strong><span>سناریو</span></div><div><strong>${money(u.balance||0)}</strong><span>تومان اعتبار</span></div></div>${u.role!=='admin'?`<form id="user-access-form"><label for="user-status">وضعیت حساب</label><select id="user-status" name="status"><option value="active" ${u.status==='active'?'selected':''}>فعال</option><option value="suspended" ${u.status==='suspended'?'selected':''}>غیرفعال / تعلیق</option></select><label>منوهای در دسترس</label><div class="permission-grid">${accessKeys.map(k=>`<label class="check-label"><input type="checkbox" name="permission" value="${k}" ${u.permissions.includes(k)?'checked':''}>${titleMap[k]}</label>`).join('')}</div><p class="hint">دسترسی‌ها در API هم کنترل می‌شوند. بخش پروفایل، پرداخت و اعلان برای پیگیری حساب در دسترس می‌مانند.</p><button type="submit" class="btn primary full">ذخیرهٔ دسترسی‌ها</button><div id="access-error"></div></form>`:'<div class="note-banner">مدیریت اصلی از این بخش قابل تعلیق یا حذف دسترسی نیست.</div>'}<form id="grant-form" class="grant-form"><h3>هدیه یا تمدید اشتراک</h3><div class="form-grid"><div><label for="grant-days">تعداد روز</label><input id="grant-days" name="days" type="number" value="30" min="1" max="3650" required></div><div><label for="grant-reason">دلیل</label><input id="grant-reason" name="reason" required maxlength="200" placeholder="هدیه، جبران، تمدید…"></div></div><button type="submit" class="btn full">${icon('plus')}افزودن روز به اشتراک</button><div id="grant-error"></div></form>`,true);$('#user-access-form')?.addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const f=new FormData(e.target),b={status:f.get('status'),permissions:f.getAll('permission')};if(state.demo)Object.assign(u,b);else await api('/admin/users/'+id,{method:'PUT',body:JSON.stringify(b)});closeDialog();await go('adminUsers');toast('دسترسی کاربر ذخیره شد.');},'#access-error');});$('#grant-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{const b=Object.fromEntries(new FormData(e.target));b.days=Number(b.days);if(state.demo){u.daysRemaining+=b.days;u.expires=Math.max(Date.now(),u.expires||0)+b.days*86400000;u.plan='gift';}else await api('/admin/users/'+id+'/subscription',{method:'POST',body:JSON.stringify(b)});closeDialog();await go('adminUsers');toast('روزهای اشتراک اضافه شد.');},'#grant-error');};}
async function sendAnnouncement(e){e.preventDefault();withForm(e.target,async()=>{const b=Object.fromEntries(new FormData(e.target));if(state.demo){const recipients=b.userId?1:adminData.users.length;adminData.announcements.unshift({...b,batch_id:crypto.randomUUID(),created:Date.now(),recipients,reads:0});if(!b.userId||b.userId==='demo-self')state.data.notifications.unshift({...b,id:crypto.randomUUID(),created:Date.now(),read_at:null});demoSave();}else await api('/admin/announcements',{method:'POST',body:JSON.stringify(b)});if(!state.demo)state.data=await api('/data');await go('adminNotices');toast('اعلان داخل پنل مخاطبان منتشر شد.');},'#notice-error');}
function extendDemoSubscription(target,days,plan){target.expires=Math.max(Date.now(),target.expires||0)+days*86400000;target.daysRemaining=Math.max(0,Math.ceil((target.expires-Date.now())/86400000));target.active=true;target.plan=plan;}
function reviewOrder(id){const o=adminData.orders.find(x=>x.id===id);dialog(`${dialogHead('بررسی سفارش',esc(o.code))}<div class="review-summary"><strong>${esc(o.name)}</strong><p>${esc(o.email)}</p><div class="invoice-details"><div><span>شرح</span><strong>${esc(o.snapshot.planName)}</strong></div><div><span>مبلغ</span><strong>${o.currency==='TRX'?Number(o.amount/1e6).toFixed(6)+' TRX':money(o.amount)+' تومان'}</strong></div><div><span>وضعیت</span>${statusPill(o.status)}</div></div><div class="proof-box"><small>اطلاعات ارسال‌شده توسط کاربر</small><p>${esc(o.proof||'هنوز مدرکی ثبت نشده است.')}</p></div></div>${o.status==='pending'?`<form id="review-form"><label for="review-status">نتیجه بررسی</label><select id="review-status" name="status"><option value="approved">تأیید و فعال‌سازی</option><option value="rejected">رد سفارش</option></select><label for="review-note">یادداشت بررسی</label><textarea id="review-note" name="note" maxlength="500" required placeholder="مرجع واریز، توضیح بررسی یا دلیل رد…"></textarea><label class="check-label"><input type="checkbox" name="confirmed">دریافت وجه را مستقل از اطلاعات کاربر بررسی کرده‌ام.</label><p class="hint">تأیید فقط یک‌بار اعمال می‌شود و در تاریخچه ثبت خواهد شد.</p><button class="btn primary full" type="submit">ثبت نتیجهٔ بررسی</button><div id="review-error"></div></form>`:`<div class="note-banner">${esc(o.note||'این سفارش نهایی شده است.')}</div>`}`);$('#review-form')?.addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const f=new FormData(e.target),b={status:f.get('status'),note:f.get('note'),confirmed:f.has('confirmed')};if(b.status==='approved'&&!b.confirmed)throw new Error('برای تأیید، بررسی مستقل دریافت وجه لازم است.');if(state.demo){if(o.status!=='pending')throw new Error('قبلاً بررسی شده است.');o.status=b.status;o.note=b.note;if(b.status==='approved'){const t=adminData.users.find(u=>u.id===o.user_id);if(t){if(o.kind==='topup')t.balance+=o.amount;else extendDemoSubscription(t,o.days,o.plan_id);}if(o.user_id==='demo-self'){if(o.kind==='topup'){state.data.wallet.balance+=o.amount;state.data.wallet.ledger.unshift({amount:o.amount,reason:'شارژ نمایشی',created:Date.now()});}else extendDemoSubscription(state.data.subscription,o.days,o.plan_id);}}demoSave();}else await api('/admin/orders/'+id+'/review',{method:'POST',body:JSON.stringify(b)});closeDialog();await go('adminOrders');toast('نتیجه ثبت شد.');},'#review-error');});}
async function saveBusiness(e){e.preventDefault();withForm(e.target,async()=>{const f=new FormData(e.target),b={...adminData.business,salesEnabled:f.has('salesEnabled'),cryptoEnabled:f.has('cryptoEnabled'),cryptoAddress:f.get('cryptoAddress'),plans:adminData.business.plans.map(p=>({...p,name:f.get('name-'+p.id),days:Number(f.get('days-'+p.id)),priceIRR:Number(f.get('price-'+p.id))*10}))};if(state.demo){adminData.business=b;state.data.business=b;demoSave();}else{adminData.business=await api('/admin/business',{method:'PUT',body:JSON.stringify(b)});state.data.business=adminData.business;}toast('تنظیمات فروش ذخیره شد.');},'#business-error');}
auth=function(){originalAuth();applyTheme();const authForm=$('#auth-form');if(authForm&&state.authMode==='password'){const soon=document.createElement('div');soon.className='social-soon';soon.innerHTML='<button type="button" disabled><b>G</b>Google <small>به‌زودی</small></button><button type="button" disabled><b>f</b>Facebook <small>به‌زودی</small></button><button type="button" disabled>'+icon('users')+'شماره موبایل <small>به‌زودی</small></button>';authForm.after(soon);}const top=$('.auth-top');if(top){const b=document.createElement('button');b.className='icon-btn';b.setAttribute('aria-label','تغییر تم ورود');b.innerHTML=icon('moon');b.onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('repol-theme',theme);document.documentElement.dataset.theme=theme;};top.appendChild(b);}const wrap=$('.auth-form-wrap');if(wrap){const more=document.createElement('div');more.className='auth-more';more.innerHTML=`<button id="explore-product" class="btn ghost full">${icon('spark')}آشنایی با ریپل و اشتراک‌ها</button>${!state.status.setup?'<button id="register-account" class="btn full">حساب ندارم؛ ثبت‌نام</button>':''}`;wrap.appendChild(more);$('#explore-product').onclick=explore;$('#register-account')?.addEventListener('click',registerForm);}const demo=$('#enter-demo');if(demo)demo.onclick=()=>{state.demo=true;demoRole='admin';state.data=structuredClone(demoData);state.page='dashboard';ensureStudio();render();window.scrollTo(0,0);};};
function registerForm(){dialog(`${dialogHead('فضای کارت را بساز.','ابتدا امکانات را تجربه کن؛ خرید اشتراک بعداً.')}<form id="register-form"><label for="reg-name">نام شما</label><input id="reg-name" name="name" autocomplete="name" required maxlength="60"><label for="reg-email">ایمیل</label><input id="reg-email" name="email" type="email" autocomplete="username" dir="ltr" required><label for="reg-password">رمز عبور</label><input id="reg-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="hint">ایمیل واقعی خودت را وارد کن؛ رمز حداقل ۱۲ کاراکتر باشد.</p><button class="btn primary full" type="submit">ساخت حساب${icon('arrow')}</button><div id="register-error"></div></form>`);$('#register-form').onsubmit=e=>{e.preventDefault();withForm(e.target,async()=>{await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.demo=false;state.page='dashboard';closeDialog();state.data=await api('/data');render();},'#register-error');};}
async function explore(){try{catalog=await api('/catalog');}catch{catalog=defaultBusiness;}$('#app').innerHTML=`<main class="product-page"><header class="product-nav">${brand()}<nav><button data-explore-scroll="product-features">امکانات</button><button data-explore-scroll="product-pricing">اشتراک‌ها</button></nav><button class="btn" id="back-login">ورود به استودیو${icon('arrow')}</button></header><section class="product-hero"><div class="product-aura"></div><span class="chip purple">REPOL STUDIO 2.0 · پیش‌نمایش محصول</span><h1>گفتگوهای تو،<br><em>آغاز اتفاق‌های بزرگ‌اند.</em></h1><p>از اولین «سلام» تا یک ارتباط ماندگار.<br>فضایی برای پاسخ‌های بهتر، مدیریت روشن‌تر و تجربه‌ای که دوستش داری.</p><div><button class="btn primary" id="public-demo">استودیو را تجربه کن${icon('arrow')}</button><button class="btn" data-explore-scroll="product-pricing">دیدن اشتراک‌ها</button></div><span class="product-small">بدون پرداخت برای پیش‌نمایش · فارسی · سازگار با موبایل</span><div class="product-mock"><div class="mock-sidebar"><span></span><i></i><i></i><i></i><i></i></div><div class="mock-main"><div class="mock-top">سلام، به ریپل خوش اومدی ✦<span>استودیوی گفتگو</span></div><div class="mock-banner">هر گفتگو، یک مسیر تازه.${icon('logo')}</div><div class="mock-stats"><span>سناریوهای تو<strong>۰۳</strong></span><span>ارتباط‌های تازه<strong>۱۲۸</strong></span><span>یک فضای آرام<strong>∞</strong></span></div><div class="mock-chart"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><div class="mock-floating">${icon('check')}پاسخ مناسب، در لحظهٔ مناسب</div></div></section><section class="product-features" id="product-features"><div class="eyeline">BUILT AROUND YOUR WORK</div><h2>جزئیات کوچک. تفاوت‌های بزرگ.</h2><div class="feature-grid">${[['flow','پاسخ‌هایت را طراحی کن','کلمهٔ کلیدی، سناریو و آزمایش پاسخ در یک مسیر روشن.'],['shield','کنترل دسترسی واقعی','کاربران مستقل، مدیریت منوها و تاریخچهٔ عملیات.'],['wallet','پرداخت قابل پیگیری','سفارش، کیف پول و اشتراک با وضعیت‌های مشخص.'],['moon','همراه سلیقهٔ تو','تم روشن و تاریک، حرکت‌های نرم و تجربهٔ موبایل.']].map(([i,t,p])=>`<article>${icon(i)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section id="product-pricing" class="product-pricing"><div class="eyeline">FIRST EXPLORE, THEN CHOOSE</div><h2>با ریتم خودت شروع کن.</h2><p>ابتدا پیش‌نمایش را ببین. اتصال واقعی سرویس‌ها هنوز در حال آماده‌سازی است.</p>${priceCards(true)}</section><footer class="product-footer">${brand()}<span>ساخته‌شده برای گفتگوهای ارزشمند.</span><a href="https://t.me/fesghli" target="_blank" rel="noopener noreferrer">ارتباط با ما @fesghli</a></footer></main>`;$('#back-login').onclick=()=>{auth();window.scrollTo(0,0);};$('#public-demo').onclick=()=>{state.demo=true;demoRole='user';state.data=structuredClone(demoData);state.page='dashboard';render();window.scrollTo(0,0);};$$('[data-public-plan]').forEach(b=>b.onclick=()=>{if(state.status.setup){auth();toast('برای شروع واقعی، ابتدا حساب مدیریت این نصب ساخته شود.');}else registerForm();});$$('[data-explore-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.exploreScroll).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));window.scrollTo(0,0);}
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('menu-open');});
document.addEventListener('click',e=>{if(e.target.closest('[data-page]'))document.body.classList.remove('menu-open');});
let syncing=false;setInterval(async()=>{if(syncing||state.demo||!state.data||document.hidden||!$('.studio-layout'))return;syncing=true;try{const r=await fetch('/api/updates');if(r.status===401){state.data=null;state.status=await api('/status');auth();toast('نشست پایان یافته یا دسترسی حساب تغییر کرده است.');return;}if(!r.ok)return;const d=await r.json();if(d.unread!==state.data.notifications.filter(n=>!n.read_at).length){const fresh=await api('/data');state.data.notifications=fresh.notifications;state.data.subscription=fresh.subscription;state.data.orders=fresh.orders;state.data.wallet=fresh.wallet;const n=$('.notification-trigger');if(n&&!$('i',n)&&d.unread)n.insertAdjacentHTML('beforeend','<i></i>');toast('اعلان تازه‌ای برایت رسیده است.');}state.data.owner=d.user;}catch{}finally{syncing=false;}},20000);
